package com.example.editor.textual.interaction;

import java.util.*;
import java.util.regex.*;
import org.springframework.stereotype.Component;
import com.example.editor.grammar.core.*;
import com.example.editor.grammar.diagnostic.*;
import com.example.editor.textual.source.*;
import com.example.editor.validation.contract.StableIdentifierPolicy;
import com.example.editor.validation.model.*;

/** Implementación neutral y determinista de las capacidades de edición que comparten Xtext y Langium. */
@Component
public class TextualLanguageFeatureService {
    private static final int MAX_COMPLETIONS=200,MAX_REFERENCES=1000,MAX_SYMBOLS=2000,MAX_TOKENS=5000,MAX_EDITS=2000;
    /** Descripción: Publica la matriz de capacidades sin confundir el fallback neutral con un runtime nativo embebido. Entradas: no requiere parámetros. Salida: devuelve estados explícitos por capacidad. */ public List<TextualInteractionCapabilityState>capabilities(){List<TextualInteractionCapabilityState>out=new ArrayList<>();for(var capability:TextualInteractionCapability.values())out.add(new TextualInteractionCapabilityState(capability,TextualInteractionExecutionMode.HYDRA_NEUTRAL,true,true,"HYDRA resuelve la capacidad sobre CanonicalModelDocument y TextualSemanticSourceMap; el runtime nativo del provider continúa siendo externo.",Map.of("nativeHost","EXTERNAL","singleSemanticIndex","true")));return List.copyOf(out);}
    /** Descripción: Calcula completion acotado reutilizando identidades, tipos y features del mismo snapshot semántico. Entradas: workspace y request. Salida: devuelve propuestas ordenadas y deterministas. */ public List<TextualCompletionItem>completion(TextualWorkspaceIndex workspace,TextualInteractionRequest request){require(workspace,request);checkInterrupted();String prefix=effectivePrefix(workspace,request);Map<String,TextualCompletionItem>items=new LinkedHashMap<>();for(CanonicalModelElement element:workspace.elements()){addCompletion(items,element.id(),"REFERENCE","Elemento "+element.classId(),element.id(),prefix);addCompletion(items,element.classId(),"TYPE","Tipo del modelo",element.classId(),prefix);for(String attribute:element.attributes().keySet())addCompletion(items,attribute,"PROPERTY","Atributo de "+element.classId(),attribute,prefix);}for(CanonicalModelRelation relation:workspace.relations())addCompletion(items,relation.relationId(),"PROPERTY","Relación canónica",relation.relationId(),prefix);int limit=Math.min(MAX_COMPLETIONS,request.maximumResults());return items.values().stream().sorted(Comparator.comparingInt(TextualCompletionItem::score).reversed().thenComparing(TextualCompletionItem::label)).limit(limit).toList();}
    /** Descripción: Obtiene hover contextual desde el source map y el modelo last-known-good. Entradas: workspace y request. Salida: devuelve información del elemento/feature bajo el cursor o un resultado vacío. */ public TextualHoverInfo hover(TextualWorkspaceIndex workspace,TextualInteractionRequest request){require(workspace,request);checkInterrupted();var entry=workspace.at(request.documentId(),new TextPosition(request.line(),request.column())).orElse(null);if(entry==null)return TextualHoverInfo.empty();CanonicalModelElement element=workspace.element(ownerSemanticId(entry)).orElse(null);String title=entry.semanticKind()+" · "+entry.semanticId();String detail=element==null?"Binding: "+entry.metamodelElementId():element.classId()+" · "+element.attributes().size()+" atributos";return new TextualHoverInfo(true,title,detail,entry.semanticId(),entry.semanticKind(),entry.documentId(),entry.range(),merge(entry.metadata(),Map.of("grammarRuleId",entry.grammarRuleId(),"metamodelElementId",entry.metamodelElementId())));}
    /** Descripción: Resuelve go-to-definition sobre la identidad semántica o el destino de una referencia. Entradas: workspace y request. Salida: devuelve la localización de definición cuando existe. */ public Optional<TextualNavigationLocation>definition(TextualWorkspaceIndex workspace,TextualInteractionRequest request){require(workspace,request);checkInterrupted();var entry=navigationEntry(workspace,request).orElse(null);if(entry==null)return Optional.empty();String target=targetSemanticId(entry);return definitionOf(workspace,target);}
    /** Descripción: Enumera referencias semánticas sin escanear documentos no relacionados. Entradas: workspace y request. Salida: devuelve localizaciones acotadas y ordenadas. */ public List<TextualNavigationLocation>references(TextualWorkspaceIndex workspace,TextualInteractionRequest request){require(workspace,request);checkInterrupted();var entry=navigationEntry(workspace,request).orElse(null);if(entry==null)return List.of();String semanticId=targetSemanticId(entry);List<TextualNavigationLocation>out=new ArrayList<>();definitionOf(workspace,semanticId).ifPresent(out::add);for(var candidate:workspace.sourceMap()){checkInterrupted();if(semanticId.equals(candidate.metadata().get("targetElementId")))out.add(location(candidate));}return out.stream().distinct().sorted(locationOrder()).limit(MAX_REFERENCES).toList();}
    /** Descripción: Construye un preview de rename coordinado para declaración y referencias sin mutar el workspace. Entradas: workspace y request. Salida: devuelve un plan seguro o conflictos accionables. */ public TextualRenamePlan rename(TextualWorkspaceIndex workspace,TextualRenameRequest request){Objects.requireNonNull(workspace,"workspace");Objects.requireNonNull(request,"request");checkInterrupted();var entry=workspace.at(request.documentId(),new TextPosition(request.line(),request.column())).orElse(null);if(entry==null)return new TextualRenamePlan(false,"",request.newId(),List.of(),List.of("No semantic element exists at the requested position"),List.of(),Map.of());String oldId=targetSemanticId(entry);List<String>conflicts=new ArrayList<>();if(!StableIdentifierPolicy.isValidElementId(request.newId()))conflicts.add("The new identifier does not satisfy HYDRA StableIdentifierPolicy");if(workspace.element(request.newId()).isPresent()&&!oldId.equals(request.newId()))conflicts.add("The new identifier already exists in the canonical model");if(oldId.equals(request.newId()))conflicts.add("The new identifier is identical to the current identifier");if(!conflicts.isEmpty())return new TextualRenamePlan(false,oldId,request.newId(),List.of(),conflicts,List.of(),Map.of("previewOnly","true"));List<GrammarTextEdit>edits=new ArrayList<>();definitionEdit(workspace,oldId,request.newId()).ifPresent(edits::add);for(var candidate:workspace.sourceMap())if(oldId.equals(candidate.metadata().get("targetElementId")))edits.add(new GrammarTextEdit(candidate.documentId(),candidate.range(),request.newId()));edits=dedupeEdits(edits).stream().limit(MAX_EDITS).toList();Set<String>docs=new TreeSet<>();edits.forEach(e->docs.add(e.documentId()));boolean safe=!edits.isEmpty()&&edits.size()<MAX_EDITS;return new TextualRenamePlan(safe,oldId,request.newId(),edits,safe?List.of():List.of("Rename could not establish a complete bounded edit set"),List.copyOf(docs),Map.of("previewOnly","true","semanticIdentityChange","true","editCount",Integer.toString(edits.size())));}
    /** Descripción: Produce formato determinista por documento sin alterar cadenas ni significado semántico. Entradas: workspace y documentId. Salida: devuelve como máximo una edición de documento completo cuando hay cambios. */ public List<GrammarTextEdit>format(TextualWorkspaceIndex workspace,String documentId){Objects.requireNonNull(workspace,"workspace");var doc=workspace.document(documentId).orElseThrow(()->new IllegalArgumentException("Unknown textual document: "+documentId));checkInterrupted();String formatted=formatText(doc.content());if(formatted.equals(doc.content()))return List.of();SourceTextIndex index=new SourceTextIndex(doc.content());return List.of(new GrammarTextEdit(documentId,index.range(0,doc.content().length()),formatted));}
    /** Descripción: Deriva símbolos de documento desde elementos trazados y preserva su orden textual. Entradas: workspace y documentId. Salida: devuelve símbolos acotados. */ public List<TextualDocumentSymbol>documentSymbols(TextualWorkspaceIndex workspace,String documentId){Objects.requireNonNull(workspace,"workspace");checkInterrupted();List<TextualDocumentSymbol>out=new ArrayList<>();for(var entry:workspace.documentEntries(documentId))if("MODEL_ELEMENT".equals(entry.semanticKind())){CanonicalModelElement element=workspace.element(entry.semanticId()).orElse(null);String name=element==null?entry.semanticId():entry.semanticId()+" : "+element.classId();out.add(new TextualDocumentSymbol(name,"MODEL_ELEMENT",entry.semanticId(),entry.range(),List.of(),Map.of("classId",element==null?"":element.classId())));}return out.stream().sorted(Comparator.comparingInt(s->s.range().start().line()*1_000_000+s.range().start().column())).limit(MAX_SYMBOLS).toList();}
    /** Descripción: Deriva rangos plegables únicamente de spans semánticos multilínea. Entradas: workspace y documentId. Salida: devuelve rangos acotados y sin duplicados. */ public List<TextualFoldingRange>folding(TextualWorkspaceIndex workspace,String documentId){Objects.requireNonNull(workspace,"workspace");checkInterrupted();LinkedHashSet<TextualFoldingRange>out=new LinkedHashSet<>();for(var entry:workspace.documentEntries(documentId))if(entry.range().end().line()>entry.range().start().line())out.add(new TextualFoldingRange(entry.range().start().line(),entry.range().end().line(),"region",entry.semanticId()));return out.stream().limit(MAX_SYMBOLS).toList();}
    /** Descripción: Proyecta source-map semántico a tokens neutrales para Monaco/LSP. Entradas: workspace y documentId. Salida: devuelve tokens ordenados y acotados. */ public List<TextualSemanticToken>semanticTokens(TextualWorkspaceIndex workspace,String documentId){Objects.requireNonNull(workspace,"workspace");checkInterrupted();List<TextualSemanticToken>out=new ArrayList<>();for(var entry:workspace.documentEntries(documentId)){int length=tokenLength(entry.range());String type=switch(entry.semanticKind()){case"MODEL_ELEMENT"->"class";case"MODEL_RELATION"->"reference";case"MODEL_FEATURE"->"property";default->"variable";};out.add(new TextualSemanticToken(entry.range().start().line(),entry.range().start().column(),length,type,entry.semanticId(),Map.of("semanticKind",entry.semanticKind(),"grammarRuleId",entry.grammarRuleId())));}return out.stream().sorted(Comparator.comparingInt(TextualSemanticToken::line).thenComparingInt(TextualSemanticToken::column)).limit(MAX_TOKENS).toList();}
    /** Descripción: Calcula invalidación incremental transitiva entre documentos usando referencias cross-document del modelo canónico. Entradas: workspace y changedDocuments. Salida: devuelve documentos impactados y si se requiere reparse completo. */ public TextualDependencyInvalidationPlan invalidation(TextualWorkspaceIndex workspace,List<String>changedDocuments){Objects.requireNonNull(workspace,"workspace");Set<String>all=new LinkedHashSet<>();workspace.documents().forEach(d->all.add(d.id()));Set<String>changed=new LinkedHashSet<>(changedDocuments==null?List.of():changedDocuments);changed.retainAll(all);Map<String,Set<String>>reverse=new LinkedHashMap<>();for(CanonicalModelRelation relation:workspace.relations()){String source=elementDocument(workspace,relation.sourceElementId()),target=elementDocument(workspace,relation.targetElementId());if(!source.isBlank()&&!target.isBlank()&&!source.equals(target))reverse.computeIfAbsent(target,ignored->new LinkedHashSet<>()).add(source);}Set<String>impacted=new LinkedHashSet<>(changed);ArrayDeque<String>queue=new ArrayDeque<>(changed);while(!queue.isEmpty()){checkInterrupted();for(String dependent:reverse.getOrDefault(queue.removeFirst(),Set.of()))if(impacted.add(dependent))queue.addLast(dependent);}Set<String>unaffected=new LinkedHashSet<>(all);unaffected.removeAll(impacted);boolean full=!all.isEmpty()&&impacted.size()==all.size();return new TextualDependencyInvalidationPlan(List.copyOf(changed),List.copyOf(impacted),List.copyOf(unaffected),full,Map.of("workspaceDocuments",Integer.toString(all.size()),"dependencyEdges",Integer.toString(reverse.values().stream().mapToInt(Set::size).sum())));}
    /** Descripción: Evalúa compatibilidad de snapshots con política fail-closed basada en identidad de gramática y hash semántico. Entradas: request. Salida: devuelve si puede reutilizarse, reparsearse o necesita migración. */ public TextualSnapshotCompatibilityReport snapshotCompatibility(TextualSnapshotCompatibilityRequest request){Objects.requireNonNull(request,"request");List<String>reasons=new ArrayList<>();boolean grammarSame=request.previousGrammarId().equals(request.currentGrammarId())&&!request.currentGrammarId().isBlank();boolean semanticSame=request.previousSemanticContractHash().equals(request.currentSemanticContractHash())&&!request.currentSemanticContractHash().isBlank();boolean providerSame=request.previousProvider().equalsIgnoreCase(request.currentProvider())&&!request.currentProvider().isBlank();boolean snapshotSame=request.previousSnapshotId().equals(request.currentSnapshotId())&&!request.currentSnapshotId().isBlank();if(!grammarSame)reasons.add("Grammar identity changed");if(!semanticSame)reasons.add("Semantic binding contract changed");if(!providerSame)reasons.add("Provider changed");if(snapshotSame&&grammarSame&&semanticSame)return new TextualSnapshotCompatibilityReport(true,false,false,List.of("Exact grammar snapshot is unchanged"),Map.of("compatibility","EXACT"));if(grammarSame&&semanticSame)return new TextualSnapshotCompatibilityReport(false,true,false,reasons.isEmpty()?List.of("Snapshot revision changed"):reasons,Map.of("compatibility","REPARSE_SAFE"));return new TextualSnapshotCompatibilityReport(false,false,true,reasons,Map.of("compatibility","MIGRATION_REQUIRED"));}
    /** Descripción: Valida argumentos comunes de consultas posicionales. Entradas: workspace y request. Salida: no devuelve valor; rechaza entradas incompletas. */ private static void require(TextualWorkspaceIndex workspace,TextualInteractionRequest request){Objects.requireNonNull(workspace,"workspace");Objects.requireNonNull(request,"request");if(request.documentId().isBlank())throw new IllegalArgumentException("documentId is required");}
    /** Descripción: Calcula el prefijo efectivo leyendo el texto cuando el cliente no lo proporciona. Entradas: workspace y request. Salida: devuelve el prefijo actual. */ private static String effectivePrefix(TextualWorkspaceIndex workspace,TextualInteractionRequest request){if(!request.prefix().isBlank())return request.prefix();var doc=workspace.document(request.documentId()).orElse(null);if(doc==null)return"";int offset=workspace.offset(request.documentId(),new TextPosition(request.line(),request.column()));int start=offset;while(start>0){char c=doc.content().charAt(start-1);if(!Character.isLetterOrDigit(c)&&c!='_'&&c!='-'&&c!='.')break;start--;}return doc.content().substring(start,offset);}
    /** Descripción: Añade una propuesta única calculando afinidad de prefijo. Entradas: items, label, kind, detail, semanticId y prefix. Salida: actualiza el mapa solo cuando la propuesta es relevante. */ private static void addCompletion(Map<String,TextualCompletionItem>items,String label,String kind,String detail,String semanticId,String prefix){if(label==null||label.isBlank())return;String lower=label.toLowerCase(Locale.ROOT),p=prefix.toLowerCase(Locale.ROOT);int score=p.isBlank()?10:lower.equals(p)?100:lower.startsWith(p)?80:lower.contains(p)?40:0;if(score>0)items.putIfAbsent(kind+"\u0000"+label,new TextualCompletionItem(label,kind,detail,label,semanticId,score,Map.of()));}
    /** Descripción: Resuelve la entrada navegable más precisa sin alterar el source map compartido. Si el cursor cae en whitespace inmediatamente anterior a una referencia, prioriza el token de relación de esa misma línea; en cualquier otro caso conserva la resolución exacta existente. Entradas: workspace y request. Salida: devuelve la entrada semántica adecuada para navegación y búsqueda de referencias. */ private static Optional<TextualSemanticSourceMapEntry> navigationEntry(TextualWorkspaceIndex workspace,TextualInteractionRequest request){TextPosition position=new TextPosition(request.line(),request.column());Optional<TextualSemanticSourceMapEntry> exact=workspace.at(request.documentId(),position);if(exact.isPresent()&&"MODEL_RELATION".equals(exact.get().semanticKind()))return exact;var doc=workspace.document(request.documentId()).orElse(null);if(doc==null)return exact;int cursorOffset=workspace.offset(request.documentId(),position);Optional<TextualSemanticSourceMapEntry> adjacent=workspace.documentEntries(request.documentId()).stream().filter(e->"MODEL_RELATION".equals(e.semanticKind())).filter(e->e.range().start().line()==request.line()).filter(e->e.range().start().column()>=request.column()).sorted(Comparator.comparingInt(e->e.range().start().column())).filter(e->{int start=workspace.offset(request.documentId(),e.range().start());if(start<cursorOffset||start-cursorOffset>2)return false;String between=doc.content().substring(cursorOffset,start);return between.chars().allMatch(Character::isWhitespace);}).findFirst();return adjacent.isPresent()?adjacent:exact;}
    /** Descripción: Resuelve la identidad propietaria de una entrada de source map. Entradas: entry. Salida: devuelve ownerId cuando existe o semanticId como fallback. */ private static String ownerSemanticId(TextualSemanticSourceMapEntry entry){return entry.metadata().getOrDefault("ownerId",entry.metadata().getOrDefault("sourceElementId",entry.semanticId()));}
    /** Descripción: Resuelve el destino semántico navegable de una entrada. Entradas: entry. Salida: devuelve targetElementId para referencias o semanticId para declaraciones/features. */ private static String targetSemanticId(TextualSemanticSourceMapEntry entry){return entry.metadata().getOrDefault("targetElementId",ownerSemanticId(entry));}
    /** Descripción: Busca la localización de declaración más precisa de una identidad. Entradas: workspace y semanticId. Salida: devuelve Optional con la definición. */ private static Optional<TextualNavigationLocation>definitionOf(TextualWorkspaceIndex workspace,String semanticId){return workspace.sourceMap().stream().filter(e->semanticId.equals(e.semanticId())&&"MODEL_ELEMENT".equals(e.semanticKind())).findFirst().map(TextualLanguageFeatureService::location);}
    /** Descripción: Convierte una entrada de source map en una localización navegable. Entradas: entry. Salida: devuelve la localización equivalente. */ private static TextualNavigationLocation location(TextualSemanticSourceMapEntry entry){return new TextualNavigationLocation(entry.documentId(),entry.range(),entry.semanticId(),entry.semanticKind(),entry.metadata());}
    /** Descripción: Define un orden total estable para localizaciones. Entradas: no requiere parámetros. Salida: devuelve comparador por documento y posición. */ private static Comparator<TextualNavigationLocation>locationOrder(){return Comparator.comparing(TextualNavigationLocation::documentId).thenComparingInt(v->v.range().start().line()).thenComparingInt(v->v.range().start().column());}
    /** Descripción: Localiza el token de declaración que contiene un ID dentro del rango del elemento. Entradas: workspace, oldId y newId. Salida: devuelve edición opcional de declaración. */ private static Optional<GrammarTextEdit>definitionEdit(TextualWorkspaceIndex workspace,String oldId,String newId){var definition=workspace.sourceMap().stream().filter(e->oldId.equals(e.semanticId())&&"MODEL_ELEMENT".equals(e.semanticKind())).findFirst().orElse(null);if(definition==null)return Optional.empty();var doc=workspace.document(definition.documentId()).orElse(null);if(doc==null)return Optional.empty();SourceTextIndex index=new SourceTextIndex(doc.content());int start=index.offset(definition.range().start()),end=index.offset(definition.range().end());Matcher matcher=Pattern.compile("(?<![A-Za-z0-9_.-])"+Pattern.quote(oldId)+"(?![A-Za-z0-9_.-])").matcher(doc.content());matcher.region(Math.max(0,start),Math.min(doc.content().length(),Math.max(start,end)));if(!matcher.find())return Optional.empty();return Optional.of(new GrammarTextEdit(definition.documentId(),index.range(matcher.start(),matcher.end()),newId));}
    /** Descripción: Elimina ediciones duplicadas conservando el primer orden determinista. Entradas: edits. Salida: devuelve lista sin duplicados exactos. */ private static List<GrammarTextEdit>dedupeEdits(List<GrammarTextEdit>edits){Map<String,GrammarTextEdit>unique=new LinkedHashMap<>();for(var edit:edits)unique.putIfAbsent(edit.documentId()+"|"+edit.range()+"|"+edit.replacement(),edit);return List.copyOf(unique.values());}
    /** Descripción: Formatea de forma conservadora normalizando LF y eliminando únicamente espacios finales, sin alterar indentación ni líneas vacías cuyo significado puede depender de la gramática. Entradas: source. Salida: devuelve texto determinista preservando la estructura de líneas. */ private static String formatText(String source){String normalized=(source==null?"":source).replace("\r\n","\n").replace('\r','\n');String[]lines=normalized.split("\n",-1);StringBuilder out=new StringBuilder(normalized.length());for(int i=0;i<lines.length;i++){checkInterrupted();out.append(stripTrailing(lines[i]));if(i<lines.length-1)out.append('\n');}return out.toString();}
    /** Descripción: Elimina solo whitespace final de una línea para no modificar indentación semánticamente relevante. Entradas: line. Salida: devuelve la línea con su prefijo intacto y sin espacios finales. */ private static String stripTrailing(String line){int end=line==null?0:line.length();while(end>0&&Character.isWhitespace(line.charAt(end-1)))end--;return line==null?"":line.substring(0,end);}
    /** Descripción: Calcula longitud visual mínima de un rango semántico. Entradas: range. Salida: devuelve longitud positiva en la línea inicial. */ private static int tokenLength(TextRange range){if(range.end().line()==range.start().line())return Math.max(1,range.end().column()-range.start().column());return Math.max(1,range.end().column());}
    /** Descripción: Resuelve el documento propietario de un elemento a partir de la definición trazada. Entradas: workspace y elementId. Salida: devuelve documentId o cadena vacía. */ private static String elementDocument(TextualWorkspaceIndex workspace,String elementId){return workspace.sourceMap().stream().filter(e->elementId.equals(e.semanticId())&&"MODEL_ELEMENT".equals(e.semanticKind())).map(TextualSemanticSourceMapEntry::documentId).findFirst().orElse("");}
    /** Descripción: Combina metadatos de forma inmutable dando prioridad al segundo mapa. Entradas: first y second. Salida: devuelve un mapa combinado. */ private static Map<String,String>merge(Map<String,String>first,Map<String,String>second){Map<String,String>out=new LinkedHashMap<>();if(first!=null)out.putAll(first);if(second!=null)out.putAll(second);return Map.copyOf(out);}
    /** Descripción: Coopera con cancelación del hilo antes de trabajos potencialmente largos. Entradas: no requiere parámetros. Salida: no devuelve valor; lanza CancellationException si existe interrupción. */ private static void checkInterrupted(){if(Thread.currentThread().isInterrupted())throw new java.util.concurrent.CancellationException("Textual interaction cancelled");}
}
